function sameBasket(a,b){const keys=Object.keys(a);return keys.length===Object.keys(b).length&&keys.every(id=>Object.hasOwn(b,id)&&a[id]===b[id]);}
async function loadCatalog(){try{let data=readInitialCatalog(document);if(!data){const r=await fetch('/api/catalog',{cache:'no-store',signal:AbortSignal.timeout(12000)});if(!r.ok)throw new Error('Kunne ikke laste katalogen');data=await r.json();}configureSiteSettings(data.settings);catalogManualOrder=data.settings?.catalogOrder||[];catalogLoaded=true;catalogProducts=data.products.filter(p=>p.rentalEnabled!==false);products=applyRentalScope(catalogProducts,rentalScope);syncCatalogCategories();if(!['Alle','Enkeltprodukter'].includes(filter)&&!getSiteSettings().categories.some(c=>c.id===filter))filter='Alle';configureBusinessPackages(products);renderPricingScope();businessChoices=cleanBusinessChoices(businessChoices);const normalized=normalizeBasket(cart,products);let changed=!sameBasket(normalized,cart);const restored=savedSofas===null?migrateSofas(normalized,products,cartLinks):restoreSofas(normalized,savedSofas,products);cart=restored.cart;sofaSetups=restored.setups;changed=changed||!sameBasket(cart,normalized);savedSofas=sofaSetups;livingPackage=products.find(p=>p.id==='stuepakke'&&isReadyPackage(p))||products.find(p=>isReadyPackage(p)&&(p.components||[]).some(c=>products.find(x=>x.id===c.id)?.type==='sofa'))||null;el('adminLink').hidden=false;const featured=document.querySelector('.package-feature'),featuredPackage=products.find(isReadyPackage);featured.hidden=!featuredPackage;if(featuredPackage){const button=featured.querySelector('[data-detail]');button.dataset.detail=featuredPackage.id;button.textContent='Se '+featuredPackage.name+' ↗';featured.querySelector('div>p:not(.eyebrow)').textContent=featuredPackage.description;const photo=featured.querySelector('figure img');photo.src=featuredPackage.image||'assets/hero.jpg';photo.alt=featuredPackage.name;featured.querySelector('figcaption').textContent=isKiPhoto(featuredPackage.image)?kiDisclosure:featuredPackage.isExample?'Bildet viser et eksempel':'';featured.querySelector('div>p.hint').textContent=featuredPackage.isProposal?'Velg antall personer og tilpass forslaget. Pris og tilgjengelighet bekreftes i tilbudet.':'Velg antall pakker og eventuelle tilvalg. Pris og tilgjengelighet bekreftes i tilbudet.';}el('catalogStatus').textContent='';if(isEnquiryPage&&!Object.keys(cart).length&&!sofaSetups.length){openShortRequest(true);return;}renderProducts();renderCart();if(isEnquiryPage)ensureRentalUsage(()=>{renderPricingScope();renderCart();});if(changed)toast('Kurven er tilpasset gjeldende beholdning og gyldige moduloppsett.');restoreCatalogPosition();const selectedId=new URL(location.href).searchParams.get('produkt');if(isProductPage||selectedId){const selected=products.find(p=>p.active&&!p.deletedAt&&p.id===selectedId);if(!selected)productPageError('Dette produktet er ikke tilgjengelig for leie. Se resten av utvalget.');else if(selected.moduleSeries)openModuleBuilder(selected.moduleSeries,new URL(location.href).searchParams.get('oppsett')||'');else if(isWall(selected))openWall(selected.id);else openProduct(selected);}}catch{enquiryFlow.fail();productPageError('Produktet kunne ikke lastes. Prøv å laste siden på nytt.');el('catalogStatus').innerHTML='Utvalget kunne ikke lastes. <button class="text-button" id="retryCatalog">Prøv igjen</button>';el('retryCatalog').onclick=loadCatalog;}}
