function openWall(id='',group=''){const target=products.find(p=>isWall(p)&&p.id===id)||products.find(p=>isWall(p)&&(!group||p.wallGroup===group));if(!target)return;if(!isProductPage){navigateProduct(target.id,'rent',{bruk:purpose,prisbruk:rentalScopeConfirmed?rentalScope:''});return;}selectPageProduct(target,'rent',{bruk:purpose,prisbruk:rentalScopeConfirmed?rentalScope:''});if(!ensureRentalUsage(()=>openWall(id,group)))return;const chosen=products.find(p=>isWall(p)&&p.id===id);wallGroup=chosen?.wallGroup||group||wallGroups()[0];wallSelection=chosen?.id||wallProducts()[0]?.id;if(!wallSelection)return;el('wallQuantity').value='1';el('wallLayouts').innerHTML=rentalWallView(rentalOptionsContext(),wallSelection).layouts;refreshWall();if(el('cart').open)el('cart').close();showSurface(el('wall'),target.name);}
