async function refreshReservedStock({force=false}={}){
 if(!catalogLoaded)return;
 const start=el('start')?.value,end=el('end')?.value,key=start+'|'+end;
 if(key===reservationKey&&!force)return;reservationKey=key;const request=++reservationRequest;
 if(!start||!end||end<start){products=applyRentalScope(catalogProducts,rentalScope);renderProducts();return;}
 try{const response=await fetch('/api/rental-availability?'+new URLSearchParams({start,end}),{cache:'no-store',signal:AbortSignal.timeout(10000)});if(!response.ok)throw Error();const data=await response.json();if(request!==reservationRequest)return;
 const adjusted=catalogProducts.map(p=>({...p,unavailable:(p.unavailable||0)+(data.reserved[p.id]||0)}));products=applyRentalScope(adjusted,rentalScope);for(const p of products){p.maxQuantity=remaining(p.id,{},products);if(!p.isService&&p.maxQuantity===0)p.rentalRentedOut=true;}
 renderProducts();if(el('detail')?.open)refreshSelection();if(el('modules')?.open)renderModuleBuilder();if(el('wall')?.open)refreshWall();
 }catch{if(request===reservationRequest)reservationKey='';}
}

